pub fn mlp_inference(x: &[i16]) -> Eval {
    const SH: usize = A_B3.len();
    let mut cat = [0.0f32; SH*2];
    shared_inference_a(&x[..Board::FN], &mut cat[..SH]);
    shared_inference_b(&x[Board::FN..], &mut cat[SH..]);
    head_inference(&cat)
}

fn layer(x: &[f32], w: &[f32], b: &[f32], y: &mut [f32], relu: bool) {
    debug_assert_eq!(w.len(), x.len() * y.len());
    debug_assert_eq!(b.len(), y.len());
    for j in 0..y.len() {
        y[j] = b[j];
        for i in 0..x.len() {
            y[j] += w[j * x.len() + i] * x[i];
        }
        if relu {
            y[j] = y[j].max(0.0);
        }
    }
}

fn shared_inference_a(x: &[i16], y: &mut [f32]) {
    let mut x0 = [0.0; Board::FN];
    for i in 0..Board::FN {
        x0[i] = x[i] as f32;
    }
    let mut x1 = [0.0; A_B1.len()];
    layer(&x0, A_W01.as_flattened(), &A_B1, &mut x1, true);
    let mut x2 = [0.0; A_B2.len()];
    layer(&x1, A_W12.as_flattened(), &A_B2, &mut x2, true);
    layer(&x2, A_W23.as_flattened(), &A_B3, y, true);
}

fn shared_inference_b(x: &[i16], y: &mut [f32]) {
    let mut x0 = [0.0; Board::FN];
    for i in 0..Board::FN {
        x0[i] = x[i] as f32;
    }
    let mut x1 = [0.0; B_B1.len()];
    layer(&x0, B_W01.as_flattened(), &B_B1, &mut x1, true);
    let mut x2 = [0.0; B_B2.len()];
    layer(&x1, B_W12.as_flattened(), &B_B2, &mut x2, true);
    layer(&x2, B_W23.as_flattened(), &B_B3, y, true);
}

fn softsign(x: f32) -> f32 {
    x / (1.0 + x.abs())
}

fn head_inference(x3: &[f32]) -> Eval {
    let mut x4 = [0.0; H_B4.len()];
    layer(&x3, H_W34.as_flattened(), &H_B4, &mut x4, true);
    let mut x5 = [0.0; H_B5.len()];
    layer(&x4, H_W45.as_flattened(), &H_B5, &mut x5, true);
    let mut x6 = [0.0; H_B6.len()];
    layer(&x5, H_W56.as_flattened(), &H_B6, &mut x6, false);
    let logit = x6[0];
    let output = (softsign(logit) * 1.5).clamp(-1.0, 1.0) * 6000.0;
    output.round() as Eval
}


